const key = req.header('Idempotency-Key');
if (!key) return res.status(400).send('Idempotency-Key required');

const prior = await idempotency.find(key, req.customerId);
if (prior) return res.status(prior.status).json(prior.body);

const result = await checkout(req.body);
await idempotency.save(key, req.customerId, result, { ttl: '24h' });
return res.status(result.status).json(result.body);
